// Build risk alert summary from Neo4j query results
const highRiskData = $('Query High Risk Suppliers').first()?.json;
const singleSourceData = $('Check Single-Source Risks').first()?.json;

const highRisk = highRiskData?.results?.[0]?.data || [];
const singleSource = singleSourceData?.results?.[0]?.data || [];

const cols1 = highRiskData?.results?.[0]?.columns || [];
const cols2 = singleSourceData?.results?.[0]?.columns || [];

const hrRows = highRisk.map(r => Object.fromEntries(cols1.map((c,i)=>[c,r.row[i]])));
const ssRows = singleSource.map(r => Object.fromEntries(cols2.map((c,i)=>[c,r.row[i]])));

const criticalCount = hrRows.filter(r => (r.score||0) >= 0.8).length;
const highCount    = hrRows.filter(r => (r.score||0) >= 0.6 && (r.score||0) < 0.8).length;

let summary = `UC4 Supply Chain Weekly Risk Report\n`;
summary += `Generated: ${new Date().toISOString()}\n\n`;
summary += `CRITICAL suppliers: ${criticalCount}\n`;
summary += `HIGH risk suppliers: ${highCount}\n`;
summary += `Single-source dependencies: ${ssRows.length}\n\n`;

if (hrRows.length > 0) {
  summary += `Top HIGH/CRITICAL risks:\n`;
  hrRows.slice(0,5).forEach(r => {
    summary += `  [${(r.score*100).toFixed(0)}%] ${r.name} (${r.country||'?'}, T${r.tier||'?'}) ${r.flags||''}\n`;
  });
}

if (ssRows.length > 0) {
  summary += `\nSingle-source risks:\n`;
  ssRows.slice(0,5).forEach(r => {
    summary += `  ${r.customer} -> ${r.supplier} (T${r.tier||'?'}, ${r.country||'?'})\n`;
  });
}

const hasAlerts = criticalCount > 0 || ssRows.length > 0;

return [{
  json: {
    summary,
    criticalCount,
    highCount,
    singleSourceCount: ssRows.length,
    hasAlerts,
    highRiskSuppliers: hrRows,
    singleSourceRisks: ssRows,
  }
}];
